   368	function createDraftTransaction(transaction: OnyxTypes.Transaction) {
   369	    if (!transaction) {
   370	        return;
   371	    }
   372	
   373	    const newTransaction = {
   374	        ...transaction,
   375	    };
   376	
   377	    Onyx.set(`${ONYXKEYS.COLLECTION.TRANSACTION_DRAFT}${transaction.transactionID}`, newTransaction);
   378	}
